import AppKit

/// The agent's two caption tools: `transcribe` (File ▸ Generate Captions…)
/// and `export_captions` (File ▸ Export Captions…) — the two directions of
/// phase 4's caption work.
///
/// They live in a file of their own rather than beside `import_captions` in
/// `AgentServer+Media.swift` for `AgentServer+Silence.swift`'s reason: neither
/// is a mirror of an op, both are app-state tools with a concern of their own
/// — one drives a speech recogniser, the other writes a subtitle container —
/// and the argument for how each is threaded belongs beside the code it
/// explains rather than three files away.
///
/// **`transcribe` runs on the SERVER thread** (`AgentServer.offMainTools`).
/// The set's criterion is "waits for something the main thread has to deliver
/// or must not be doing", and a transcription is the second half of it:
/// `SpeechEngine.transcribe` blocks its caller on a semaphore while a
/// detached analysis runs (it refuses the main thread outright), and a
/// transcription is seconds to minutes of work that must not freeze the UI.
/// `detect_silence` was kept OUT
/// of the set on the same criterion read the other way — it reads a few
/// hundred KB and returns — and that is the distinction, not "touches the
/// disk".
///
/// **`export_captions` runs on the MAIN thread**, where every other
/// non-`offMainTools` handler runs: writing a few KB of text synchronously
/// waits on nothing and has no completion to deliver, which is
/// `import_captions`' own argument in the opposite direction.
extension AgentServer {

    // MARK: - Transcribing

    /// `transcribe` — File ▸ Generate Captions… (`TranscribeSheetController`,
    /// whose language popup, clip scope and progress bar are these arguments
    /// and this result). On-device speech recognition over the clips' own
    /// audio, laid out as ordinary text clips through the same
    /// `CaptionLayout.place` an imported `.srt` goes through, so a generated
    /// caption and an imported one are the same kind of thing afterwards.
    ///
    /// **Runs on the server thread** (`AgentServer.offMainTools`) and calls
    /// `Transcriber.transcribe` — the SYNCHRONOUS body its own doc offers "a
    /// tool that already runs on the server thread" — rather than `run`,
    /// whose completion is posted to main for a sheet's benefit. There is
    /// therefore no semaphore here at all: the wait is the call.
    ///
    /// **It needs no grant and never downloads** (spec §11 W-8).
    /// `SpeechTranscriber` asks for no Speech Recognition grant (W0 q1), so
    /// there is no grant tier. A language whose model is not INSTALLED is
    /// refused by name — "a person has to install it" — because a download
    /// is a person's act, done from the sheet's Download row, never a tool's
    /// (R6-12's argument read across).
    ///
    /// **The order of the refusals is deliberate**, and the LANGUAGE question
    /// is split across it, because its two halves are not the same kind of
    /// question. The caller's own mistakes — a clip id that names nothing, a
    /// scope with nothing audible in it, and a language tag the engine has
    /// never heard of — are answered FIRST. Only then is it asked whether
    /// this Mac has the MODEL for the language that was named
    /// (`Transcriber.languages()`, the installed list), and only then does
    /// the run start.
    ///
    /// **Since road map 6's C1 it has TWO engines** (§5g), and this method
    /// owns only the choice between them: `engine` is read after the
    /// caller's own model mistakes and before anything either engine does,
    /// and each arm is then the code it was or is
    /// (`AgentServer+CloudCaptions.swift`). The order of the refusals, end to
    /// end: the unknown clip and the empty scope (the scope), a misspelt
    /// `engine` with both spellings named, then — under `apple` — a
    /// cloud-only argument refused BY NAME, the language's spelling and the
    /// installed model; or — under `assemblyai` — the three cloud arguments'
    /// own types, the credential, the endpoint, a media over ten hours, and
    /// only then the network. Neither engine reports `truncated`: W2 deleted
    /// the key with the ceiling it reported.
    ///
    /// **`style` and `replace` (road map 8 §5i, W4a)** are the caller's own
    /// mistakes too, so they are read with `place` and `language`, before
    /// the scope: a misspelt style is refused with the six named, and
    /// `replace` is refused by name with `subtitles` or with `place: false`,
    /// where it could do nothing. The tracks it replaces are found at
    /// COMMIT time, against the handle the plan is built on.
    ///
    /// **`slide`, `fill` and `dim` (spec §11 W-15)** are read next, after
    /// `replace`'s refusals and before the scope (`captionLooks`): a `true`
    /// with a style the look shows nothing on, then with `place: false`, is
    /// refused by name; a `false` is always accepted — a second rule in this
    /// one tool, since `replace` and the three cloud-only arguments refuse on
    /// PRESENCE. The remembered checkboxes are never read (R6-2 read across).
    func transcribe(_ a: [String: Any]) throws -> String {
        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
        // `importMedia`'s guard, restated: everything below assumes the main
        // thread is free, which is only true while this handler is not
        // standing on it.
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "transcribe must run on the server thread — its name is missing from "
                    + "AgentServer.offMainTools.")
        }
        let place = try boolArg(a, "place") ?? true
        let wanted = try stringArg(a, "language")
        let style = try captionStyle(a)
        let replace = try boolArg(a, "replace")
        if replace != nil {
            guard style.isWordStyle else {
                throw ToolError(
                    message: "replace only applies with a word caption style — one of "
                        + CaptionStyle.allCases.filter(\.isWordStyle).map(\.rawValue)
                            .joined(separator: ", ")
                        + " — not subtitles.")
            }
            guard place else {
                throw ToolError(
                    message: "replace only applies when place is true: with place false "
                        + "nothing is placed, so nothing is replaced.")
            }
        }
        let asked = try captionLooks(a, style: style, place: place)

        let document = try onMain { try self.target(a) }
        // The scope, the jobs and the frame in ONE main-thread hop, so every
        // decision below is made against one snapshot rather than against
        // however many the document had while we were hopping. `Job` carries
        // everything by value for the same reason.
        let scope = try onMain { try self.transcriptionScope(a, document) }
        guard !scope.jobs.isEmpty else { throw scope.emptyRefusal }
        let pages = CaptionPages.Request(style: style, canvas: scope.canvas)

        let outcome: Transcriber.Outcome
        var fields: [String: Any]
        switch try transcriptionEngine(a) {
        case .apple:
            // An argument that can only mean something to AssemblyAI is the
            // caller's own mistake and is named before any work starts.
            try refuseCloudOnlyArguments(a)

            // A tag the framework has never heard of is a typo, and a typo is
            // the caller's own mistake, so it is answered here with the rest
            // of them. See the two-part note in this method's doc.
            try Self.checkSpelling(of: wanted)
            let language = try Self.transcriptionLanguage(wanted)

            // Held on this stack for the whole call, as `export` holds its
            // `Exporter`.
            let transcriber = Transcriber()
            // The assistant's Stop reaches the run through the sheet's own token (AI-16).
            let token = Transcriber.CancelToken()
            stop?.onCancel { token.cancel() }
            do {
                outcome = try transcriber.transcribe(
                    scope.jobs, language: language, frame: scope.frame, pages: pages,
                    cancel: token)
            } catch {
                // Every failure comes back in band, message and all —
                // including "no speech was recognised", which is a true
                // answer about the audio rather than a transport problem.
                throw ToolError(message: error.localizedDescription)
            }
            fields = [
                "engine": TranscriptionEngine.apple.rawValue,
                "language": language.identifier,
            ]
        case .assemblyai:
            let answer = try cloudTranscription(
                a, document: document, jobs: scope.jobs, frame: scope.frame, pages: pages,
                language: wanted)
            outcome = answer.outcome
            fields = answer.fields
        }

        // Ticks, not seconds: every other tool speaks the model's own unit and
        // the catalog has one sentence for it.
        // A word style's cue adds its `words`, in the same timeline ticks,
        // and `size` only where a lone word shrank.
        let reported: [[String: Any]] = outcome.cues.map { cue in
            var row: [String: Any] = ["start": cue.start, "end": cue.end, "text": cue.text]
            if let words = cue.words {
                row["words"] = words.map { ["start": $0.start, "end": $0.end, "text": $0.text] }
            }
            if let size = cue.size { row["size"] = size }
            return row
        }
        var problems = scope.problems + outcome.problems
        fields["cues"] = reported
        fields["clips_read"] = outcome.clips.map { Int($0) }

        // `place: false` is a read, like `detect_silence`: no ops, no undo
        // step, and the caller places the cues itself or does not.
        guard place else {
            fields["ok"] = true
            fields["placed"] = false
            if !problems.isEmpty { fields["skipped"] = problems.map { $0.description } }
            return try onMain {
                fields["project"] = self.summary(document)
                return try self.jsonResult(fields)
            }
        }
        return try onMain {
            // The plan is built at COMMIT time against the document's CURRENT
            // handle. Recognition is asynchronous work that took real seconds,
            // and `CaptionLayout.place` probes the handle to learn the ids its
            // own ops will mint — so a plan built before the recognition
            // could patch ids that no longer mean what it thought.
            let plan: CaptionLayout.Plan
            do {
                let replacing = replace == true
                    ? CaptionLayout.replaceableTracks(
                        in: document.editedProject.snapshot, jobs: scope.jobs)
                    : []
                plan = try CaptionLayout.place(
                    outcome.cues, problems: problems, in: document.editedProject,
                    style: style, looks: asked.looks, replacing: replacing)
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
            problems = plan.problems
            fields["placed"] = true
            fields["captions"] = plan.clips
            if let name = plan.trackName { fields["track_name"] = name }
            if plan.trimmed > 0 { fields["trimmed"] = plan.trimmed }
            if replace != nil { fields["replaced"] = plan.replaced.map { Int($0) } }
            if asked.given { fields["looks"] = asked.looks.names }
            if !problems.isEmpty { fields["skipped"] = problems.map { $0.description } }
            return try self.editResult(document, "Generate Captions", plan.ops, fields)
        }
    }

    /// What a run will read, what it will not, and the frame it measures
    /// against — everything `Transcriber` needs, by value.
    ///
    /// Main thread only: it reads the snapshot and the document's media URLs.
    private func transcriptionScope(
        _ a: [String: Any], _ document: ProjectDocument
    ) throws -> TranscriptionScope {
        // The OPEN container's, because the ops this run produces are
        // addressed to it (road map 2's phase 9). Reading the document and
        // writing into the nest is one gesture measuring against one timeline
        // and landing in another; `SilenceDetector` and `AudioNormalize` were
        // moved off that shape in the same phase, and File ▸ Generate
        // Captions… reads the same handle for the same reason.
        let snapshot = document.editedProject.snapshot
        let named = try optionalClipsArg(a, "clips", document)
        let clips = named.map { ids in ids.compactMap { snapshot.clip($0) } } ?? snapshot.clips
        let outcome = Transcriber.jobs(
            for: clips, in: snapshot, urls: document.mediaURLs(),
            maps: document.editedProject.sourceMap)
        // An unnamed scope is every clip in the project, and most of them are
        // legitimately not speech — listing "clip 3: its source is not a media
        // file" for a whole timeline would bury the one entry that matters.
        // Only clips the caller ASKED for are reported, which is
        // `import_captions`' rule read across: it reports what the caller's
        // own file was too malformed to use.
        let problems = named == nil ? [] : outcome.problems
        return TranscriptionScope(
            jobs: outcome.jobs, problems: problems, named: named != nil,
            frame: max(snapshot.canvas.fps.frameDuration, 1),
            canvas: CGSize(width: snapshot.canvas.width, height: snapshot.canvas.height))
    }

    /// The `style` argument, refused BY NAME with all six spellings when it
    /// is not one of them; Subtitles when absent, so today's calls are
    /// unchanged.
    private func captionStyle(_ a: [String: Any]) throws -> CaptionStyle {
        try enumArg(a, "style", CaptionStyle.self) ?? .subtitles
    }

    /// `slide`, `fill` and `dim` (spec §11 W-15): the looks the call asked
    /// for, and whether it gave any of the three keys at all — which is what
    /// puts `looks` in a placed answer. A `true` that would show nothing is
    /// refused BY NAME, the style first and then `place`, each list of
    /// styles from `CaptionLooks.Look.styleList`; a `false` is always
    /// accepted. Only the call is read: never the sheet's remembered boxes.
    private func captionLooks(
        _ a: [String: Any], style: CaptionStyle, place: Bool
    ) throws -> (looks: CaptionLooks, given: Bool) {
        var looks = CaptionLooks.none
        var given = false
        for look in CaptionLooks.Look.allCases {
            guard let value = try boolArg(a, look.rawValue) else { continue }
            given = true
            looks[look] = value
        }
        for look in CaptionLooks.Look.allCases where looks[look] {
            guard look.isLive(for: style) else {
                throw ToolError(
                    message: "\(look.rawValue) only applies with style \(look.styleList) — not "
                        + "\(style.rawValue).")
            }
        }
        for look in CaptionLooks.Look.allCases where looks[look] {
            guard place else {
                throw ToolError(
                    message: "\(look.rawValue) only applies when place is true: with place "
                        + "false nothing is placed, so nothing is styled.")
            }
        }
        return (looks, given)
    }

    /// The jobs a run will do, and how to refuse when there are none.
    private struct TranscriptionScope {
        let jobs: [Transcriber.Job]
        let problems: [CaptionLayout.Problem]
        /// Whether the caller named the clips, which decides which refusal
        /// is the honest one: "none of THOSE" or "nothing here at all".
        let named: Bool
        let frame: Ticks
        /// What the pager measures pages against.
        let canvas: CGSize

        var emptyRefusal: AgentServer.ToolError {
            guard named else {
                return ToolError(
                    message: "Nothing in this timeline has recorded sound to transcribe. Only a "
                        + "clip playing a movie or sound file can be, and not one played in "
                        + "reverse.")
            }
            let reasons = problems.map { $0.description }.joined(separator: "; ")
            return ToolError(
                message: "None of those clips can be transcribed"
                    + (reasons.isEmpty ? "." : " — " + reasons + "."))
        }
    }

    /// The first half of the language question: is this a language tag at
    /// ALL? Everything the framework names passes, model or no model.
    ///
    /// It is a separate function because it is a separate PROBLEM with a
    /// separate fix. A tag the engine has never heard of is a misspelling and
    /// is retyped; a tag it knows that this Mac has no model for is a
    /// download a person makes, and `transcriptionLanguage` below refuses
    /// that one in those words. One refusal for both would send somebody
    /// whose only problem was an uninstalled model back to check a tag that
    /// was right all along — which is what `transcribe`'s catalog entry
    /// promises does not happen, and the promise is the reason this half
    /// exists.
    ///
    /// It refuses only where that list is NON-EMPTY. An empty one is not
    /// evidence that a tag is wrong — it is evidence that the question could
    /// not be asked at all (`SpeechEngine.askBound`) — and "no such language"
    /// off it would be a false answer.
    static func checkSpelling(of wanted: String?) throws {
        guard let wanted = wanted else { return }
        let known = Transcriber.supportedLanguages()
        guard !known.isEmpty, Transcriber.language(matching: wanted, in: known) == nil else {
            return
        }
        throw ToolError(
            message: Transcriber.TranscribeError.unknownLanguage(wanted).localizedDescription
                + " It knows \(known.count): " + list(known) + ".")
    }

    /// The second half: the `language` argument as one of the rows the
    /// sheet's popup shows, refused BY NAME when this Mac has no on-device
    /// MODEL for it — the argument vocabulary's rule applied to a vocabulary
    /// that is the machine's rather than the model's.
    ///
    /// `Transcriber.language(matching:in:)` does the matching (an identifier,
    /// a bare language code, or the display name), and
    /// `Transcriber.defaultLanguage` the fallback, so the tool and the popup
    /// cannot drift apart.
    static func transcriptionLanguage(_ wanted: String?) throws -> Transcriber.Language {
        let languages = Transcriber.languages()
        guard !languages.isEmpty else {
            throw ToolError(
                message: "This Mac has no ON-DEVICE speech model installed for any language. "
                    + "A person has to install one: open File ▸ Generate Captions…, choose a "
                    + "language under Language, and press Download.")
        }
        guard let wanted = wanted else {
            guard let fallback = Transcriber.defaultLanguage(in: languages) else {
                throw ToolError(
                    message: "No language could be chosen. Pass language with one of: "
                        + list(languages) + ".")
            }
            return fallback
        }
        guard let match = Transcriber.language(matching: wanted, in: languages) else {
            throw notInstalledRefusal(for: wanted, ready: languages)
        }
        return match
    }

    /// "This Mac has no model for a language it otherwise understands" — the
    /// not-installed refusal, and the only way past `checkSpelling` that is
    /// still about the language. It never downloads: a person does, from the
    /// sheet (spec §11 W-8).
    ///
    /// The display NAME comes back out of the engine's list rather than
    /// being echoed as the caller typed it, because "French (France) is not
    /// installed" reads as a fact about a language where "fr is not
    /// installed" reads as a fact about a string. A tag that
    /// arrives here with no name to be found can only mean the framework's
    /// list was empty when `checkSpelling` asked it, and then the tag is the
    /// best name there is — one message with a fallback, rather than a third
    /// arm that nothing can reach, which is the shape this whole refusal was
    /// found in.
    private static func notInstalledRefusal(
        for wanted: String, ready: [Transcriber.Language]
    ) -> ToolError {
        let known = Transcriber.supportedLanguages()
        let name = Transcriber.language(matching: wanted, in: known)?.displayName ?? wanted
        return ToolError(
            message: Transcriber.TranscribeError.notInstalled(name).localizedDescription
                + " Ready to use here: " + list(ready) + ".")
    }

    /// The identifiers of either list, capped: the engine names thirty here
    /// and an error message that prints them all is not read at all.
    private static func list(_ languages: [Transcriber.Language]) -> String {
        let names = languages.map { $0.identifier }.sorted()
        guard names.count > 24 else { return names.joined(separator: ", ") }
        return names.prefix(24).joined(separator: ", ") + ", …and \(names.count - 24) more"
    }

    // MARK: - Exporting captions

    /// `export_captions` — File ▸ Export Captions… (`CaptionExporter`, which
    /// owns the two containers and the round-trip rule). Writes one text
    /// track's clips out as SubRip (`.srt`) or WebVTT (`.vtt`). It edits
    /// nothing, so it answers through `jsonResult` rather than `editResult`
    /// and registers no undo step.
    ///
    /// **The track is never guessed**, and the rule is `CaptionExporter`'s
    /// rather than restated here: the default is the single track whose clips
    /// are all text, and with none or with more than one
    /// `CaptionExporter.resolveTrack` refuses and its `ExportError` LISTS the
    /// candidates by id, name and cue count. That is the posture
    /// `remove_media` takes for media still in use and `export` takes for an
    /// unknown size; picking the front-most candidate would write the wrong
    /// file and report success.
    ///
    /// The one thing this handler owns is the PATH, because a path is an
    /// argument rather than a caption question: the format is resolved first
    /// (an explicit `format` wins, else the path's own extension, else
    /// SubRip) so `captionDestinationURL` can replace a wrong extension rather
    /// than append to it — `talk.srt` asked for as `vtt` is `talk.vtt`, not
    /// `talk.srt.vtt`.
    func exportCaptions(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        // The open container's, so the track this writes is the one
        // `get_project` is listing.
        let snapshot = document.editedProject.snapshot
        let path = try requiredString(a, "path")
        let expanded = (path as NSString).expandingTildeInPath
        let format = CaptionExporter.format(
            for: URL(fileURLWithPath: expanded), requested: try requestedFormat(a))
        let url = try Self.requireFolder(of: Self.captionDestinationURL(path, format: format))

        // Read through `trackArg` rather than handed to the exporter raw, so
        // an id that names nothing is refused as "No track has id N" here
        // instead of arriving there as a track with no clips.
        var requestedTrack: UInt32?
        if a["track"] != nil, !(a["track"] is NSNull) {
            requestedTrack = try trackArg(a, "track", document).id
        }
        let outcome: (track: UInt32, format: CaptionExporter.Format, cues: [CaptionExporter.Cue])
        do {
            outcome = try CaptionExporter.export(
                from: snapshot, track: requestedTrack, to: url, format: format)
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        return try jsonResult([
            "ok": true,
            // The URL that was WRITTEN, never the argument: `destinationURL`
            // replaces a wrong extension, and every caller reports what
            // actually landed so the substitution is never silent.
            "path": url.path,
            "format": outcome.format.rawValue,
            "track": Int(outcome.track),
            "track_name": snapshot.track(outcome.track)?.name ?? "",
            "cues": outcome.cues.count,
            "project": summary(document),
        ])
    }

    /// The file `export_captions` writes for `path` (spec §11 #43): only a
    /// trailing `srt` or `vtt` (`CaptionExporter.knownExtensions`) is
    /// replaced by the format's own, and any other extension is part of the
    /// name — `chart.png` is `chart.png.srt` — which is the save panel's rule
    /// (`CaptionExporter.renamed`), so the panel and the tool agree.
    static func captionDestinationURL(_ path: String, format: CaptionExporter.Format) -> URL {
        destinationURL(
            path, extension: format.rawValue, replacing: CaptionExporter.knownExtensions)
    }

    /// The `format` argument, refused BY NAME when it is not one of the two
    /// containers — nil when it is absent, which is what lets
    /// `CaptionExporter.format(for:requested:)` fall back to the path.
    private func requestedFormat(_ a: [String: Any]) throws -> CaptionExporter.Format? {
        try enumArg(a, "format", CaptionExporter.Format.self, folding: true)
    }
}

import Foundation

/// `get_timeline_transcript` (road map "creator-jobs" TX1, spec §11 TX-10…
/// TX-13): every heard word of the edited container in timeline order,
/// nested instances included, each with its clip, track, editability and a
/// stable identity, read on this Mac once per media and kept
/// (`TranscriptFill`, TX-12).
///
/// An APP-STATE read, `get_transcript`'s posture: nothing is edited, no undo
/// step, never the network, so no AI-7 row and no key (TX-14). **It runs on
/// the SERVER thread** (`creatorOffMainTools`): the fill blocks for seconds
/// to minutes. The document, the plan, the snapshot, the arguments and each
/// heard media's cached transcript are read in ONE main-thread hop; the
/// assistant's Stop withdraws this call's want from the fill
/// (`AgentLane.shared.callCancel`, AI-16), which cancels a run no other owner
/// wants.
///
/// Since TX3a (spec §11 TX-30, TX-33) each word carries `cut_start` and
/// `cut_end`, the cut the Transcript tab makes of it selected alone
/// (`TranscriptCut.wordCut`: widened, snapped) over every read word of
/// `tracks`, before the window and paging, against the container as this
/// call read it; each needed media's voice cache is read here, off main.
/// Since TX3b (spec §11 TX-34) the same table answers `pauses[]`: each voice-
/// cache silence over 1 s between two words of one clip, with the cut the tab
/// makes of it, one row per pause whose word before is on the page.
extension AgentServer {

    /// What the main-thread hop read.
    private struct TimelineTranscriptContext {
        let document: ProjectDocument
        let snapshot: ProjectSnapshot
        let window: TranscriptReader.Window?
        let tracks: Set<UInt32>?
        let instances: [TimelineTranscript.Instance]
        let noWords: [TimelineTranscript.NoWords]
        let cloud: [UInt32: TimelineTranscript.MediaWords]
        let records: [UInt32: MediaSnapshot]
        let urls: [UInt32: URL]
        let cacheDir: URL?
        let playhead: Ticks
        let fill: TranscriptFill
    }

    /// `get_timeline_transcript {from?, to?, tracks?, language?}`. Refused,
    /// in order: the window (TR-13's `.empty`, then outside the timeline), an
    /// unknown track by name, the language's spelling, then — only when a
    /// heard media needs this Mac's words — the installed model, and a
    /// failed or cancelled fill with the recogniser's sentence.
    func getTimelineTranscript(_ a: [String: Any]) throws -> String {
        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16, TX-13)
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "get_timeline_transcript must run on the server thread — its name is "
                    + "missing from AgentServer.creatorOffMainTools.")
        }
        let context = try onMain { try self.timelineTranscriptContext(a) }
        let wanted = try stringArg(a, "language")
        try Self.checkSpelling(of: wanted)

        // The media the window needs: the playhead's first, then by first start.
        let window = context.window
        let needed = TimelineTranscript.neededMedia(
            context.instances, window: window, playhead: context.playhead)

        var media = context.cloud.filter { needed.contains($0.key) }
        let device = needed.filter { context.cloud[$0] == nil }
        if !device.isEmpty {
            let language = try Self.transcriptionLanguage(wanted)
            media.merge(
                try deviceWords(device, language: language, context: context, stop: stop),
                uniquingKeysWith: { first, _ in first })
        }

        let all = TimelineTranscript.words(
            context.instances, media: media, snapshot: context.snapshot)
        let windowed = window.map { TimelineTranscript.overlapping(all, in: $0) } ?? all
        var notes = TimelineTranscript.sameSpeech(windowed, instances: context.instances)
        let kept = context.tracks.map { tracks in windowed.filter { tracks.contains($0.track) } }
            ?? windowed
        let page = TimelineTranscript.page(kept, fps: context.snapshot.canvas.fps)
        let table = cutTable(all, context: context, heard: media)
        let cuts = wordCuts(page.words, table: table, context: context)
        let pauses = pauseRows(page.words, table: table, context: context)
        if needed.contains(where: { media[$0]?.fillersReported == false }) {
            notes.append(
                "These words were not transcribed with filler words, so a filler missing here "
                    + "may still be in the audio.")
        }
        for id in needed where media[id]?.voiceCacheMissing == true {
            notes.append(Self.unmovedNote(context.records[id]?.name ?? "media \(id)"))
        }

        var result: [String: Any] = [
            "ok": true,
            "count": page.words.count,
            "words": zip(page.words, cuts).map { Self.wordRow($0, cut: $1) },
            "pauses": pauses,
            "media": needed.compactMap { media[$0] }.map { heard -> [String: Any] in
                var row: [String: Any] = [
                    "media": Int(heard.media), "engine": heard.engine.rawValue,
                    "fillers_reported": heard.fillersReported,
                ]
                if let language = heard.language { row["language"] = language }
                return row
            },
            "no_words": context.noWords.map {
                [
                    "clip": Int($0.clip), "nest_path": $0.nestPath.map { Int($0) },
                    "tag": $0.tag, "reason": $0.reason,
                ] as [String: Any]
            },
            "notes": notes,
        ]
        if let window {
            result["from"] = window.from
            result["to"] = window.to
        }
        if let next = page.nextFrom {
            result["truncated"] = true
            result["next_from"] = next
        }
        return try onMain {
            result["project"] = self.summary(context.document)
            return try self.jsonResult(result)
        }
    }

    /// The one main-thread hop: the document, the edited container's plan
    /// and snapshot, the window and `tracks`, the instances, the clips with
    /// no words and each heard media's cached transcript.
    private func timelineTranscriptContext(_ a: [String: Any]) throws -> TimelineTranscriptContext {
        let document = try target(a)
        let edited = document.editedProject
        let snapshot = edited.snapshot
        let window: TranscriptReader.Window?
        do {
            window = try TimelineTranscript.window(
                from: try optionalTimeArg(a, "from", document),
                to: try optionalTimeArg(a, "to", document), duration: snapshot.duration)
        } catch let error as TranscriptReader.WindowError {
            throw ToolError(message: error.localizedDescription)
        } catch let error as TimelineTranscript.WindowError {
            throw ToolError(message: error.localizedDescription)
        }
        var tracks: Set<UInt32>?
        if let ids = try intsArg(a, "tracks") {
            let scope = try idScope(document)
            tracks = []
            for id in ids {
                guard let track = UInt32(exactly: id), scope.tracks.contains(where: { $0.id == track })
                else {
                    throw ToolError(message: scope.noSuchId("track", UInt32(clamping: id)))
                }
                tracks?.insert(track)
            }
        }
        guard let read = TimelineTranscript.read(document: document) else {
            throw ToolError(message: "The timeline's composition plan could not be read.")
        }
        var cloud: [UInt32: TimelineTranscript.MediaWords] = [:]
        if let cacheDir = read.cacheDir {
            for instance in read.instances {
                let id = instance.job.media
                guard cloud[id] == nil, let record = read.records[id],
                    let words = TimelineTranscript.cloudWords(
                        record, url: instance.job.source, cacheDir: cacheDir)
                else { continue }
                cloud[id] = words
            }
        }
        return TimelineTranscriptContext(
            document: document, snapshot: read.snapshot, window: window, tracks: tracks,
            instances: read.instances, noWords: read.noWords, cloud: cloud, records: read.records,
            urls: read.urls, cacheDir: read.cacheDir, playhead: read.playhead,
            fill: TranscriptFill.fill(for: document))
    }

    /// This Mac's words for each media: a stored whole-file run, else one
    /// read by the fill as this call's want (TX-12).
    private func deviceWords(
        _ ids: [UInt32], language: Transcriber.Language, context: TimelineTranscriptContext,
        stop: AgentCallCancel?
    ) throws -> [UInt32: TimelineTranscript.MediaWords] {
        guard let cacheDir = context.cacheDir else {
            throw ToolError(message: "The project has no cache folder to keep the words in.")
        }
        var out: [UInt32: TimelineTranscript.MediaWords] = [:]
        var items: [TranscriptFill.Item] = []
        for id in ids {
            guard let record = context.records[id], let url = context.urls[id] else { continue }
            guard
                let item = TimelineTranscript.fillItem(
                    record, url: url, cacheDir: cacheDir, language: language)
            else {
                throw ToolError(message: "“\(record.name)” cannot be read.")
            }
            if let words = TimelineTranscript.deviceWords(item) {
                out[id] = words
            } else {
                items.append(item)
            }
        }
        guard !items.isEmpty else { return out }
        let fill = context.fill
        let owner = fill.newOwner()
        fill.want(owner: owner, items: items)
        stop?.onCancel { fill.release(owner: owner) }
        let outcomes = fill.wait(owner: owner)
        fill.release(owner: owner)
        if outcomes.values.contains(.cancelled) {
            throw ToolError(message: Transcriber.TranscribeError.cancelled.localizedDescription)
        }
        for item in items {
            if case .failed(let why)? = outcomes[item.media] { throw ToolError(message: why) }
            guard let words = TimelineTranscript.deviceWords(item) else {
                throw ToolError(
                    message: "What was heard in “\(item.name)” could not be read back from the "
                        + "project's cache.")
            }
            out[item.media] = words
        }
        return out
    }

    /// The cut's table of every read word of `tracks`, with each heard
    /// media's voice cache. Server thread.
    private func cutTable(
        _ all: [TimelineTranscript.Word], context: TimelineTranscriptContext,
        heard: [UInt32: TimelineTranscript.MediaWords]
    ) -> TranscriptCut.Table {
        var speech: [UInt32: [Float]] = [:]
        if let cacheDir = context.cacheDir {
            for media in heard.keys {
                speech[media] = MediaImporter.loadSpeech(for: media, in: cacheDir)
            }
        }
        return TranscriptCut.Table(
            all: all, tracks: context.tracks,
            context: TranscriptCut.Context(
                instances: context.instances, media: heard, speech: speech))
    }

    /// Each page word's `TranscriptCut.wordCut` over `table`.
    private func wordCuts(
        _ page: [TimelineTranscript.Word], table: TranscriptCut.Table,
        context: TimelineTranscriptContext
    ) -> [TranscriptCut.Range] {
        var token: [TimelineTranscript.Identity: Int] = [:]
        for (index, at) in table.shown.enumerated() { token[table.all[at].id] = index }
        let fps = context.snapshot.canvas.fps
        return page.map { word in
            guard let index = token[word.id] else {
                return TranscriptCut.Range(start: word.start, end: word.end)
            }
            return TranscriptCut.wordCut(index, table: table, container: context.snapshot, fps: fps)
        }
    }

    /// TX-18's note for a media read with no voice cache: its on-device
    /// starts are the recogniser's.
    static func unmovedNote(_ name: String) -> String {
        "The word starts of “\(name)” are where this Mac's recogniser put them, often early: "
            + "it has no voice cache yet. Call again once it has."
    }

    /// The pauses of `table` (TX-34) whose word before is on `page`:
    /// `{start, end, cut_start, cut_end, clip, track, media, follows,
    /// precedes}`, the span, the tab's cut and the two words' ids.
    private func pauseRows(
        _ page: [TimelineTranscript.Word], table: TranscriptCut.Table,
        context: TimelineTranscriptContext
    ) -> [[String: Any]] {
        let onPage = Set(page.map(\.id))
        return TranscriptCut.pauses(table, fps: context.snapshot.canvas.fps).compactMap { pause in
            let before = table.word(pause.after)
            guard onPage.contains(before.id) else { return nil }
            return [
                "start": pause.span.start, "end": pause.span.end,
                "cut_start": pause.cut.start, "cut_end": pause.cut.end,
                "clip": Int(before.clip), "track": Int(before.track), "media": Int(before.media),
                "follows": Self.idRow(before.id), "precedes": Self.idRow(table.word(pause.after + 1).id),
            ]
        }
    }

    /// A word's identity as a row: `{nest_path, media, source, k}`.
    static func idRow(_ id: TimelineTranscript.Identity) -> [String: Any] {
        [
            "nest_path": id.nestPath.map { Int($0) }, "media": Int(id.media), "source": id.source,
            "k": id.k,
        ]
    }

    /// A word's row; with `cut`, its `cut_start` and `cut_end` (TX-30: always
    /// `TranscriptCut.wordCut`, never the unwidened `own`).
    static func wordRow(
        _ word: TimelineTranscript.Word, cut: TranscriptCut.Range? = nil
    ) -> [String: Any] {
        var row: [String: Any] = [
            "text": word.text, "start": word.start, "end": word.end, "clip": Int(word.clip),
            "track": Int(word.track), "media": Int(word.media), "engine": word.engine.rawValue,
            "filler": word.filler, "editable": word.editable,
            "id": idRow(word.id),
        ]
        if let speaker = word.speaker { row["speaker"] = speaker }
        if let why = word.why { row["why"] = why }
        if let cut {
            row["cut_start"] = cut.start
            row["cut_end"] = cut.end
        }
        return row
    }
}
import Foundation

/// `get_media_analysis` (spec §11 CJ-25; road map "creator-jobs" CJ2a): any
/// analysis kind of one media or clip, made on this Mac or read from its
/// cache — `shots`, the hard cuts, first, `masks`, the person masks' runs
/// (CO1, spec §11 CO-14, `AgentServer+AnalysisMasks.swift`), and `faces`, the
/// face samples (CJ3, spec §11 CJ-34, `AgentServer+AnalysisFaces.swift`),
/// `sound_events`, Sound Analysis' groups per window (FC3, spec §11
/// FC-33, `AgentServer+AnalysisSoundEvents.swift`), and `subjects`, the
/// people and salient regions (VR1, spec §11 VR-14,
/// `AgentServer+AnalysisSubjects.swift`).
/// `get_transcript`'s counterpart for pictures and sounds.
///
/// An APP-STATE tool and a read: nothing is edited and no undo step is made.
/// **It runs on the SERVER thread** (`creatorOffMainTools`), for
/// `get_transcript`'s reason: a job runs seconds to a minute. ONE main-thread
/// hop resolves the document, the arguments, the cache folder, the file and
/// the request; the call wants it under an owner of its own (alive while the
/// document is open and the assistant's Stop has not been pressed), waits
/// HOLDING the agent lane's lock as `get_transcript` does, and releases the
/// owner on every exit. After the wait it reads captured values only, but for
/// the summary's last hop.
extension AgentServer {

    /// What the one main-thread hop resolves.
    struct AnalysisCall {
        let document: ProjectDocument
        let kind: AnalysisKind
        let media: MediaSnapshot
        let clip: AnalysisClipTimes?
        let from: Ticks
        let to: Ticks
        let request: AnalysisRequest?
        let cacheDir: URL
    }

    /// `get_media_analysis` — refused in CJ-25's order: not exactly one of
    /// `media` and `clip`; an unknown id; not a media clip; for
    /// `sound_events` a reversed clip (FC-33); a media with no moving picture
    /// (a picture kind) or no sound (`sound_events`); the file missing; `to` ≤ `from`; the wait's bound;
    /// the answer's cap.
    func getMediaAnalysis(_ a: [String: Any]) throws -> String {
        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "get_media_analysis must run on the server thread — its name is "
                    + "missing from AgentServer.creatorOffMainTools.")
        }
        let call = try onMain { try self.resolveAnalysisCall(a) }
        let lane = AnalysisLane.shared
        var ran: AnalysisRun?
        if let request = call.request {
            let owner = lane.newOwner()
            defer { lane.release(owner: owner) }
            let document = call.document
            lane.want(
                [request], owner: owner,
                alive: { document.isOpenForAnalysis && !(stop?.isCancelled ?? false) },
                settled: { document.packageContentsDidChangeOnDisk() })
            let outcome = lane.wait(
                for: [request], owner: owner,
                deadline: Date().addingTimeInterval(AnalysisLane.callWaitLimit),
                cancelled: { stop?.isCancelled ?? false })
            switch outcome {
            case .landed: ran = lane.run(of: request)
            case .failed(let why):
                throw ToolError(
                    message: "The \(call.kind.rawValue) analysis of media \(call.media.id) "
                        + "failed: \(why).")
            case .cancelled:
                throw ToolError(
                    message: "The \(call.kind.rawValue) analysis of media \(call.media.id) was "
                        + "stopped before it finished.")
            case .timedOut:
                throw ToolError(message: Self.timedOutSentence(call))
            }
        }
        var result = try Self.analysisAnswer(call, ran: ran)
        return try onMain {
            result["project"] = self.summary(call.document)
            return try self.jsonResult(result)
        }
    }

    // MARK: - The main-thread hop

    private func resolveAnalysisCall(_ a: [String: Any]) throws -> AnalysisCall {
        func given(_ key: String) -> Bool { a[key] != nil && !(a[key] is NSNull) }
        guard given("media") != given("clip") else {
            throw ToolError(
                message: "Name exactly one of media and clip: the media file to analyse, or "
